<script lang="ts">
	import { toasts, removeToast, type ToastPosition } from './toasts.svelte.js';
	import Toast from './Toast.svelte';
	import RenderContent from '../util/RenderContent.svelte';
	import { BROWSER } from 'esm-env';

	const positions: ToastPosition[] = [
		'top-left', 'top-center', 'top-right',
		'bottom-left', 'bottom-center', 'bottom-right'
	];

	let containerRefs: Record<string, HTMLDivElement | undefined> = $state({});

	function hasToasts(position: ToastPosition): boolean {
		return toasts[position].length > 0;
	}

	$effect(() => {
		if (!BROWSER) return;
		for (const position of positions) {
			const el = containerRefs[position];
			if (!el) continue;
			
			if (hasToasts(position)) {
				if (!el.matches(':popover-open')) {
					el.showPopover();
				}
			} else {
				if (el.matches(':popover-open')) {
					el.hidePopover();
				}
			}
		}
	});
</script>

{#each positions as position}
	<div
		bind:this={containerRefs[position]}
		popover="manual"
		class="ToastContainer {position}"
	>
		{#each toasts[position] as item (item.id)}
			{#if item.component || item.render}
				<div class="ToastItem">
					<RenderContent 
						component={item.component}
						props={item.props}
						render={item.render}
						arg={() => removeToast(item.id)}
					/>
				</div>
			{:else}
				<Toast
					id={item.id}
					title={item.title}
					content={item.content}
					icon={item.icon}
				/>
			{/if}
		{/each}
	</div>
{/each}

<style>
	.ToastContainer {
		position: fixed;
		display: flex;
		flex-direction: column;
		gap: var(--toast-gap, var(--space-sm));
		pointer-events: none;
		margin: 0;
		padding: 0;
		border: none;
		background: transparent;
		max-width: min(var(--toast-max-width, 24rem), calc(100svw - var(--toast-offset, 1rem) * 2));
	}

	.ToastContainer :global(> *) {
		pointer-events: auto;
	}

	.top-left {
		inset: calc(var(--toast-offset, 1rem) + env(safe-area-inset-top, 0px)) auto auto calc(var(--toast-offset, 1rem) + env(safe-area-inset-left, 0px));
	}
	.top-center {
		inset: calc(var(--toast-offset, 1rem) + env(safe-area-inset-top, 0px)) auto auto 50%;
		translate: -50% 0;
	}
	.top-right {
		inset: calc(var(--toast-offset, 1rem) + env(safe-area-inset-top, 0px)) calc(var(--toast-offset, 1rem) + env(safe-area-inset-right, 0px)) auto auto;
	}
	.bottom-left {
		inset: auto auto calc(var(--toast-offset, 1rem) + env(safe-area-inset-bottom, 0px)) calc(var(--toast-offset, 1rem) + env(safe-area-inset-left, 0px));
		flex-direction: column-reverse;
	}
	.bottom-center {
		inset: auto auto calc(var(--toast-offset, 1rem) + env(safe-area-inset-bottom, 0px)) 50%;
		translate: -50% 0;
		flex-direction: column-reverse;
	}
	.bottom-right {
		inset: auto calc(var(--toast-offset, 1rem) + env(safe-area-inset-right, 0px)) calc(var(--toast-offset, 1rem) + env(safe-area-inset-bottom, 0px)) auto;
		flex-direction: column-reverse;
	}

	.ToastItem {
		animation: toast-enter 0.2s ease-out;
	}

	@media (prefers-reduced-motion: reduce) {
		.ToastItem {
			animation: none;
		}
	}
</style>

